{
  "technical_and_design_decisions": [
    "Capabilities are represented as three string maps in channel config: root/channel, application, and orderer; each map key indicates a required feature, and V1.1 is the only key for v1.1.",
    "Capability checks are exposed via component-specific interfaces (e.g., OrdererCapabilities, ApplicationCapabilities) in fabric/common/channelconfig/api.go, so consumers call semantically named methods rather than checking versions.",
    "Binaries that do not support a required capability crash immediately on channel participation, ensuring data integrity.",
    "Orderer group capabilities must be enabled before application group capabilities, enforced in config validation to prevent forks.",
    "Read-Your-Writes (RYW) is implemented by adding stub.GetTrxState (or similar) that reads from the current transaction's write set before querying the state database.",
    "MSPConfig is changed from a concrete struct to an interface to allow external construction of channel config blocks without configtxgen.",
    "Chaincode singletons are removed and replaced with explicit dependency injection or context passing to improve testability.",
    "Test World config is extended to template core.yaml and orderer.yaml from in-memory configuration objects.",
    "New lifecycle validation interface returns endorsement policy; the '+lifecycle' system chaincode uses an auto-generated majority-of-orgs signature policy initially, with later support for channel config policies.",
    "Performance evaluation of CouchDB uses existing benchmark tooling (e.g., Caliper or custom Go clients) against a local test network."
  ],
  "assumptions": [
    "A single developer with strong familiarity with the Hyperledger Fabric codebase performs all work.",
    "The codebase is at v1.0/v1.1 and changes are implemented on a branch targeting v1.1.",
    "Protobuf definitions for channel config can be extended without major breaking changes; necessary protobuf changes are minimal and included in the effort.",
    "The video and PowerPoint for U3 are produced by the developer using standard desktop tools; no external production help is needed.",
    "Performance tests are run on a modest local multi-node environment and results are indicative rather than exhaustive tuning.",
    "The 'later' extension for evaluating channel config policies as endorsement policies in U8 is included in scope as a basic implementation.",
    "All activities include writing and running unit/integration tests where applicable; CI infrastructure already exists."
  ],
  "activities": [
    {
      "activity_id": "ACT-01",
      "activity_name": "Design capabilities framework interfaces and config schema",
      "activity_description": "Define the three capability maps in channel config and the component capability interfaces in fabric/common/channelconfig/api.go, including method signatures for V1.1 behavior switches.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-02",
      "activity_name": "Implement capabilities config parsing and V1.1 logic",
      "activity_description": "Implement reading of channel, application, and orderer capability maps, define V1.1 capability in capabilities package, and cause binaries to crash when unsupported capabilities are required.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "ACT-03",
      "activity_name": "Enforce orderer capability before application capability",
      "activity_description": "Add config validation logic ensuring orderer group capabilities are enabled before application group capabilities can be set, preventing blockchain fork.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-04",
      "activity_name": "Test capabilities framework",
      "activity_description": "Write unit and integration tests covering capability detection, crash behavior, and rolling upgrade scenario across channels.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-05",
      "activity_name": "Implement RYW GetTrxState chaincode API",
      "activity_description": "Extend chaincode shim with stub.GetTrxState (or equivalent) to optionally return keys already updated in the current transaction by reading from the transaction write set.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-06",
      "activity_name": "Test RYW chaincode API",
      "activity_description": "Write unit and chaincode simulation tests verifying read-your-writes semantics during transaction execution.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "ACT-07",
      "activity_name": "Create org addition diagram (PPT)",
      "activity_description": "Produce a PowerPoint (or equivalent) diagram illustrating the process of adding an organization to a running Fabric network without downtime.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "ACT-08",
      "activity_name": "Produce org addition video and process doc",
      "activity_description": "Script, record, and edit a video demonstrating dynamic org addition, and write a detailed step-by-step process document.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "ACT-09",
      "activity_name": "Setup CouchDB performance test harness",
      "activity_description": "Deploy a test network with CouchDB as state database and configure benchmarking scripts/tools to measure query performance.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Run CouchDB performance tests and report",
      "activity_description": "Execute performance tests, collect metrics for Fabric queries with CouchDB, and produce a performance report.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-11",
      "activity_name": "Refactor MSPConfig to interface",
      "activity_description": "Change MSPConfig from a struct to an interface, update configtxgen and other consumers to allow constructing channel config blocks externally.",
      "most_likely_effort": 35
    },
    {
      "activity_id": "ACT-12",
      "activity_name": "Test external channel config construction",
      "activity_description": "Write tests that build channel config blocks outside configtxgen using the new MSPConfig interface.",
      "most_likely_effort": 15
    },
    {
      "activity_id": "ACT-13",
      "activity_name": "Remove chaincode singletons",
      "activity_description": "Refactor chaincode packages to eliminate global singletons, introducing explicit dependency passing to facilitate lifecycle work.",
      "most_likely_effort": 45
    },
    {
      "activity_id": "ACT-14",
      "activity_name": "Update tests after singleton removal",
      "activity_description": "Adapt existing unit and integration tests to the non-singleton chaincode architecture.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-15",
      "activity_name": "Generate yaml configs from World config",
      "activity_description": "Enhance the test World configuration to dynamically generate peer core.yaml and orderer.yaml files based on set values.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-16",
      "activity_name": "Test generated yaml configs",
      "activity_description": "Verify that generated YAML configurations correctly boot peer and orderer nodes in tests.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-17",
      "activity_name": "Implement lifecycle validation interface",
      "activity_description": "Implement the new lifecycle interface that returns validation parameters for a chaincode, including the '+lifecycle' edge case with auto-generated majority signature policy.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "ACT-18",
      "activity_name": "Support channel config policies in lifecycle",
      "activity_description": "Extend the lifecycle validation interface to support evaluating channel config policies as endorsement policies.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "ACT-19",
      "activity_name": "Integration testing and build verification",
      "activity_description": "Perform end-to-end integration testing across all features and ensure the full project builds and passes CI.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "ACT-20",
      "activity_name": "Documentation of new features",
      "activity_description": "Write developer documentation for capabilities framework, new shim API, MSPConfig interface, and lifecycle changes (excluding the video).",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 530
  }
}

